'use client';
import { cn } from '@/registry/default/lib/utils';
import { AnimatePresence, Transition, motion } from 'motion/react';
import {
  Children,
  cloneElement,
  ReactElement,
  useEffect,
  useState,
  useId,
} from 'react';

export type AnimatedBackgroundProps = {
  children:
    | ReactElement<{ 'data-id': string }>[]
    | ReactElement<{ 'data-id': string }>;
  defaultValue?: string;
  onValueChange?: (newActiveId: string | null) => void;
  className?: string;
  transition?: Transition;
  enableHover?: boolean;
};

export default function AnimatedBackground({
  children,
  defaultValue,
  onValueChange,
  className,
  transition,
  enableHover = false,
}: AnimatedBackgroundProps) {
  const [activeId, setActiveId] = useState<string | null>(null);
  const uniqueId = useId();

  const handleSetActiveId = (id: string | null) => {
    setActiveId(id);

    if (onValueChange) {
      onValueChange(id);
    }
  };

  // Adjust state when the controlled default value changes (React's endorsed pattern)
  const [prevDefaultValue, setPrevDefaultValue] = useState(defaultValue);
  if (defaultValue !== undefined && defaultValue !== prevDefaultValue) {
    setPrevDefaultValue(defaultValue);
    setActiveId(defaultValue);
  }

  return Children.map(children, (child: any, index) => {
    const id = child.props['data-id'];

    const interactionProps = enableHover
      ? {
          onMouseEnter: () => handleSetActiveId(id),
          onMouseLeave: () => handleSetActiveId(null),
        }
      : {
          onClick: () => handleSetActiveId(id),
        };

    return cloneElement(
      child,
      {
        key: index,
        className: cn('relative inline-flex', child.props.className),
        'data-checked': activeId === id ? 'true' : 'false',
        ...interactionProps,
      },
      <>
        <AnimatePresence initial={false}>
          {activeId === id && (
            <motion.div
              layoutId={`background-${uniqueId}`}
              className={cn('absolute inset-0', className)}
              transition={transition}
              initial={{ opacity: defaultValue ? 1 : 0 }}
              animate={{
                opacity: 1,
              }}
              exit={{
                opacity: 0,
              }}
            />
          )}
        </AnimatePresence>
        <div className='z-10'>{child.props.children}</div>
      </>
    );
  });
}

import AnimatedBackground from '@/registry/default/ui/animated-background';

export default function AnimatedNavLinksHover() {
    const TABS = ['Home', 'Services', 'Pricing', 'Contact'];

    return (
        <div className='flex items-center justify-center min-h-[10rem]'>
            <div className='flex flex-row'>
                <AnimatedBackground
                    defaultValue={TABS[0]} // Remove this if you don’t want any tab to be highlighted by default.
                    className='rounded-md bg-zinc-100 dark:bg-zinc-800'
                    transition={{
                        type: 'spring',
                        bounce: 0.2,
                        duration: 0.3,
                    }}
                    enableHover
                >
                    {TABS.map((tab, index) => (
                        <button
                            key={index}
                            data-id={tab}
                            type='button'
                            className='px-2 py-0.5 inline-flex items-center justify-center text-center text-zinc-800 transition-transform active:scale-[0.98] dark:text-zinc-50'
                        >
                            {tab}
                        </button>
                    ))}
                </AnimatedBackground>
            </div>
        </div>
    );
}

import AnimatedBackground from '@/registry/default/ui/animated-background';

export default function AnimatedTabsHover() {

    return (
        <div className='flex items-center justify-center min-h-[10rem]'>
            <div className='rounded-[8px] bg-gray-100 p-[2px] dark:bg-zinc-800'>
                <AnimatedBackground
                    defaultValue='Overview'
                    className='rounded-lg bg-white dark:bg-zinc-700'
                    transition={{
                        ease: 'easeInOut',
                        duration: 0.2,
                    }}
                >
                    {['Overview', 'Integrations', 'Activity', 'Domains'].map((label, index) => {
                        return (
                            <button
                                key={index}
                                data-id={label}
                                type='button'
                                aria-label={`${label} view`}
                                className='inline-flex w-[8rem] py-[0.4rem] items-center justify-center text-center text-zinc-800 transition-transform active:scale-[0.98] dark:text-zinc-50'
                            >
                                {label}
                            </button>
                        );
                    })}
                </AnimatedBackground>
            </div>
        </div>
    );
}

